CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL);
CREATE TABLE tenants(id TEXT PRIMARY KEY, name TEXT NOT NULL) STRICT;
CREATE TABLE departments(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, UNIQUE(id,tenant_id)) STRICT;
CREATE TABLE users(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), department_id TEXT NOT NULL, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('employee','manager','hr','it','admin','pm')), manager_id TEXT REFERENCES users(id), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), FOREIGN KEY(department_id,tenant_id) REFERENCES departments(id,tenant_id), UNIQUE(id,tenant_id)) STRICT;
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL) STRICT;
CREATE TABLE login_attempts(key TEXT PRIMARY KEY, failures INTEGER NOT NULL, window_start INTEGER NOT NULL) STRICT;
CREATE TABLE services(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), code TEXT NOT NULL, name_ar TEXT NOT NULL, name_en TEXT NOT NULL, department_id TEXT NOT NULL, description TEXT NOT NULL, fields TEXT NOT NULL CHECK(json_valid(fields)), approval_policy TEXT NOT NULL CHECK(json_valid(approval_policy)), version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,code,version), UNIQUE(id,tenant_id), FOREIGN KEY(department_id,tenant_id) REFERENCES departments(id,tenant_id)) STRICT;
CREATE TABLE projects(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, brief TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(id,tenant_id)) STRICT;
CREATE TABLE project_members(project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(project_id,user_id)) STRICT;
CREATE TABLE requests(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), requester_id TEXT NOT NULL, service_id TEXT NOT NULL, project_id TEXT, title TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), status TEXT NOT NULL CHECK(status IN ('draft','pending','returned','approved','in_progress','completed','rejected','cancelled')), version INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL DEFAULT 0, assigned_to TEXT REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(requester_id,tenant_id) REFERENCES users(id,tenant_id), FOREIGN KEY(service_id,tenant_id) REFERENCES services(id,tenant_id), FOREIGN KEY(project_id,tenant_id) REFERENCES projects(id,tenant_id), UNIQUE(id,tenant_id)) STRICT;
CREATE TABLE request_versions(request_id TEXT NOT NULL REFERENCES requests(id), revision INTEGER NOT NULL, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), created_at TEXT NOT NULL, PRIMARY KEY(request_id,revision)) STRICT;
CREATE TABLE approval_steps(id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES requests(id), revision INTEGER NOT NULL, position INTEGER NOT NULL, approver_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('pending','approved','returned','rejected')), note TEXT NOT NULL DEFAULT '', decided_at TEXT, UNIQUE(request_id,revision,position)) STRICT;
CREATE TABLE attachments(id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES requests(id), added_by TEXT NOT NULL REFERENCES users(id), filename TEXT NOT NULL, media_type TEXT NOT NULL, size INTEGER NOT NULL CHECK(size BETWEEN 1 AND 2097152), digest TEXT NOT NULL, content BLOB NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), request_id TEXT NOT NULL REFERENCES requests(id), kind TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL) STRICT;
CREATE TABLE audit_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id TEXT NOT NULL REFERENCES tenants(id), actor_id TEXT NOT NULL REFERENCES users(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL, policy_version TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE outbox(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), request_id TEXT NOT NULL REFERENCES requests(id), event_key TEXT NOT NULL UNIQUE, event_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'blocked' CHECK(status IN ('blocked')), reason TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE tasks(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, assignee_id TEXT NOT NULL REFERENCES users(id), due_date TEXT NOT NULL, acceptance TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','completed')), evidence TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL) STRICT;
CREATE INDEX requests_owner ON requests(tenant_id,requester_id,status);
CREATE INDEX approval_inbox ON approval_steps(approver_id,status,request_id);
CREATE INDEX audit_entity ON audit_events(tenant_id,entity_type,entity_id);
CREATE INDEX notifications_user ON notifications(user_id,created_at);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'audit is append only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'audit is append only'); END;
CREATE TRIGGER version_no_update BEFORE UPDATE ON request_versions BEGIN SELECT RAISE(ABORT,'submitted versions are immutable'); END;
CREATE TRIGGER version_no_delete BEFORE DELETE ON request_versions BEGIN SELECT RAISE(ABORT,'submitted versions are immutable'); END;
CREATE TRIGGER service_no_update BEFORE UPDATE ON services BEGIN SELECT RAISE(ABORT,'create a new service version'); END;
CREATE TRIGGER service_no_delete BEFORE DELETE ON services BEGIN SELECT RAISE(ABORT,'service versions are immutable'); END;
CREATE TRIGGER member_tenant BEFORE INSERT ON project_members WHEN NOT EXISTS(SELECT 1 FROM projects p JOIN users u ON u.tenant_id=p.tenant_id WHERE p.id=NEW.project_id AND u.id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'cross tenant membership'); END;
CREATE TRIGGER step_tenant BEFORE INSERT ON approval_steps WHEN NOT EXISTS(SELECT 1 FROM requests r JOIN users u ON u.tenant_id=r.tenant_id WHERE r.id=NEW.request_id AND u.id=NEW.approver_id AND r.requester_id<>u.id) BEGIN SELECT RAISE(ABORT,'invalid approver'); END;
